#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BMiraActiveExecutionTests {
  const string Root="D:/Project/LASTRAIL/";
  internal static JObject Packet()=> (JObject)((JArray)JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/combat-b-active-projectile-source-traces-20261003.json"))["traces"]).Single(t=>(string)t["name"]=="actual-mira-active")["response"].DeepClone();
  internal static BCarriageBuffDefinitions Definitions(){var json=File.ReadAllText(Root+"QA/CombatBMigration-20261002/BuffConsumer/original-definitions.json");using var sha=SHA256.Create();return new BCarriageBuffDefinitions(json,BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(json))).Replace("-","").ToLowerInvariant());}
  static object Invoke(object target,string method,params object[] args){var m=target is Type t?t.GetMethod(method):target.GetType().GetMethod(method);Assert.NotNull(m,"Missing actual B ACTIVE owner boundary: "+method);try{return m.Invoke(target is Type?null:target,args);}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();throw;}}
  internal static BDirectAttackBasicLoop Fresh(JObject p=null,int capacity=10000){p=p??Packet();return (BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),"CreateActiveValidation",p,(string)p["packetHash"],Definitions(),capacity);}
  static JObject Request(BDirectAttackBasicLoop s,string id="cast")=>(JObject)Invoke(s,"RequestActive",id);
  static JObject Active(BDirectAttackBasicLoop s)=>(JObject)s.Capture()["active"];
  static void Advance(BDirectAttackBasicLoop s,int ticks,string id="advance")=>s.Advance(id,10000L*ticks,ticks);
  [Test] public void ActualBSourceAcceptsAndSixDelayedImpactsChangeNativeHp(){var s=Fresh();var r=Request(s);Assert.AreEqual("WINDUP",(string)r["phase"]);Assert.AreEqual(9260,(long)r["readyTick"]);Advance(s,299,"pre");Assert.AreEqual(700,s.Hp("enemy"));Advance(s,1,"emit");Assert.AreEqual(1,((JArray)Active(s)["shots"]).Count);Assert.AreEqual(700,s.Hp("enemy"));Advance(s,119,"flight");Assert.AreEqual(700,s.Hp("enemy"));Advance(s,1,"hit");Assert.AreEqual(687,s.Hp("enemy"));Advance(s,1000,"rest");Assert.AreEqual(622,s.Hp("enemy"));Assert.AreEqual(6,((JArray)Active(s)["shots"]).Count);Assert.IsTrue(((JArray)Active(s)["shots"]).All(x=>(string)x["status"]=="RESOLVED_HIT"));}
  [Test] public void DuplicateCommandReturnsOriginalAcceptanceWithoutRestart(){var s=Fresh();var r=Request(s);Advance(s,300);var before=s.Capture();Assert.IsTrue(JToken.DeepEquals(r,Request(s)));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void FullRestorePreservesEmissionPendingImpactAndResolution(){foreach(int tick in new[]{300,419,420,1420}){var s=Fresh();Request(s);Advance(s,tick);var cache=s.Capture();var restored=(BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),"RestoreActiveValidation",cache,Packet(),(string)Packet()["packetHash"],Definitions(),10000);Assert.IsTrue(JToken.DeepEquals(cache,restored.Capture()));if(tick<1420){Advance(s,1420-tick,"tail");Advance(restored,1420-tick,"tail");Assert.IsTrue(JToken.DeepEquals(s.Capture(),restored.Capture()));Assert.AreEqual(622,restored.Hp("enemy"));}}}
  [Test] public void RehashedDifferentSourceIsNotTrusted(){var p=Packet();p["projectile"]["travelMs"]=1;Assert.Throws<ArgumentException>(()=>Fresh(p));}
  static JObject Observation(string id,string op)=>new JObject{["kind"]="LOCAL_ORIGINAL",["eventId"]=id,["operation"]=op};
  static void Observe(BDirectAttackBasicLoop s,JObject value)=>s.ApplyOriginalActiveObservation(value);
  static void Damage(BDirectAttackBasicLoop s,string target,int amount,string id){var v=Observation(id,"DAMAGE");v["targetId"]=target;v["amount"]=amount;Observe(s,v);}
  static void Target(BDirectAttackBasicLoop s,bool present,bool range,string generation=null){var v=Observation("target-change","TARGET");var target=(JObject)Packet()["initialTargetIdentity"].DeepClone();if(generation!=null)target["generation"]=generation;v["identity"]=target;v["present"]=present;v["range"]=range;Observe(s,v);}
  [Test] public void DownBeforeWindupCancelsAllUnfiredWithoutRefund(){var s=Fresh();Request(s);Advance(s,100);Damage(s,"op_mira",1520,"down");Advance(s,1320,"tail");Assert.AreEqual(700,s.Hp("enemy"));Assert.AreEqual(0,((JArray)Active(s)["shots"]).Count);Assert.AreEqual(9260,(long)Active(s)["readyTick"]);}
  [Test] public void ThirdShotThenDownRetainsLaunchedShots(){var s=Fresh();Request(s);Advance(s,700);Damage(s,"op_mira",1520,"down");Advance(s,720,"tail");Assert.AreEqual(661,s.Hp("enemy"));Assert.AreEqual(3,((JArray)Active(s)["shots"]).Count);}
  [TestCase(false,true)][TestCase(true,false)][TestCase(true,true)] public void TargetLifecycleAndRangeHaveDistinctImpactRules(bool present,bool range){var s=Fresh();Request(s);Advance(s,300);Target(s,present,range,present&&range?"replacement":null);Advance(s,1120,"tail");Assert.AreEqual(present?(range?668:687):700,s.Hp("enemy"));Assert.AreEqual(present&&!range?"RESOLVED_HIT":"RESOLVED_MISS",(string)Active(s)["shots"][0]["status"]);Assert.AreEqual(1,((JArray)Active(s)["shots"]).Count);}
  [Test] public void AttackFreezesAtFirstActualEmission(){var s=Fresh();Request(s);Advance(s,300);var v=Observation("attack-change","ATTACK");v["value"]=new JObject{["numerator"]="1000",["denominator"]="1"};Observe(s,v);Advance(s,1120,"tail");Assert.AreEqual(622,s.Hp("enemy"));var shots=(JArray)Active(s)["shots"];Assert.IsTrue(shots.All(x=>JToken.DeepEquals(x["emission"]["attackSnapshot"],shots[0]["emission"]["attackSnapshot"])));}
  [Test] public void BodyBreakChangesOnlyLaterShotModifier(){var s=Fresh();Request(s);Advance(s,300);Damage(s,"a_physical1",1000,"break");Advance(s,1120,"tail");var shots=(JArray)Active(s)["shots"];Assert.AreNotEqual((string)shots[0]["emission"]["modifierSourceHash"],(string)shots[1]["emission"]["modifierSourceHash"]);Assert.IsTrue(JToken.DeepEquals(shots[0]["emission"]["attackSnapshot"],shots[5]["emission"]["attackSnapshot"]));Assert.AreEqual(9260,(long)Active(s)["readyTick"]);}
  [TestCase("IMMUNITY")][TestCase("SHIELD")][TestCase("DEFENSE")] public void ImpactUsesCurrentNativeDefenseImmunityAndShield(string kind){var s=Fresh();Request(s);Advance(s,300);var v=Observation("defense-change",kind);if(kind=="IMMUNITY")v["value"]=true;else if(kind=="DEFENSE")v["value"]=new JObject{["numerator"]="50000",["denominator"]="1"};else{v["amount"]=100;v["expiry"]=2000;}Observe(s,v);Advance(s,120,"impact");Assert.Greater(s.Hp("enemy"),687);Assert.AreEqual("RESOLVED_HIT",(string)Active(s)["shots"][0]["status"]);}
  [Test] public void PauseAndOddHalfDebtRestorePreserveOriginalClock(){var s=Fresh();Request(s);s.SetSpeed("slow",3);s.Advance("half",1,1);Assert.AreEqual(0,s.Tick);var cache=s.Capture();var r=(BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),"RestoreActiveValidation",cache,Packet(),(string)Packet()["packetHash"],Definitions(),10000);s.SetPaused("pause",true);r.SetPaused("pause",true);s.Advance("paused",10000000,1000);r.Advance("paused",10000000,1000);s.SetPaused("resume",false);r.SetPaused("resume",false);s.Advance("tail",2800000,1000);r.Advance("tail",2800000,1000);Assert.IsTrue(JToken.DeepEquals(s.Capture(),r.Capture()));Assert.AreEqual(420,s.Tick);Assert.AreEqual(687,s.Hp("enemy"));}
  [Test] public void SplitAdvanceMatchesNativeHpAndEmissionWire(){var a=Fresh();var b=Fresh();Request(a);Request(b);Advance(a,1420);for(int i=0;i<142;i++)Advance(b,10,"split-"+i);Assert.AreEqual(a.Hp("enemy"),b.Hp("enemy"));Assert.IsTrue(JToken.DeepEquals(Active(a),Active(b)));}
  [Test] public void AutoAndManualUseSingleCooldownOwner(){var auto=Fresh();Advance(auto,301);Assert.AreEqual(9261,(long)Active(auto)["readyTick"]);Assert.AreEqual("REJECTED_BUSY",(string)Request(auto,"manual")["requestStatus"]);Advance(auto,1300,"recovery");Assert.AreEqual("REJECTED_COOLDOWN",(string)Request(auto,"too-soon")["requestStatus"]);}
  [Test] public void TerminalCleansInFlightAndNeverAddsHpDamage(){var s=Fresh();Request(s);Advance(s,300);Damage(s,"a_local_train",5000,"terminal");Assert.AreEqual("TERMINAL",(string)Active(s)["phase"]);Assert.AreEqual("CLEANED_TERMINAL",(string)Active(s)["shots"][0]["status"]);Advance(s,1120,"after");Assert.AreEqual(700,s.Hp("enemy"));}
  [Test] public void CapacityFailureDoesNotPublishPartialCast(){var s=Fresh(capacity:1);s.SetActiveAuto("auto-off",false);var before=s.Capture();Assert.Throws<ArgumentException>(()=>Request(s));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void CacheTamperingCannotRestoreIndependentProjectileState(){var s=Fresh();Request(s);Advance(s,300);foreach(string area in new[]{"active","activeOwner","state"}){var bad=s.Capture();bad[area]["unknown"]=1;Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.RestoreActiveValidation(bad,Packet(),(string)Packet()["packetHash"],Definitions(),10000));}}
  [Test] public void ResumedBasicUsesSameCurrentTargetImmunity(){var s=Fresh();Request(s);var v=Observation("immune","IMMUNITY");v["value"]=true;Observe(s,v);Advance(s,1600);Assert.AreEqual(700,s.Hp("enemy"));}
  [Test] public void ReplacementDoesNotInheritPreviousTargetImmunity(){var s=Fresh();Request(s);Advance(s,300);var v=Observation("immune","IMMUNITY");v["value"]=true;Observe(s,v);Target(s,true,true,"replacement");Advance(s,1300,"resume-basic");Assert.Less(s.Hp("enemy"),700);Assert.AreEqual("RESOLVED_MISS",(string)Active(s)["shots"][0]["status"]);}
 }
}
#endif
